B.Jk=new A.ap([B.cu,"\u0422\u043e\u0431\u0456 \u043f\u043e\u0434\u043e\u0431\u0430\u0454\u0442\u044c\u0441\u044f \u043f\u0435\u0440\u0435\u0442\u0432\u043e\u0440\u044e\u0432\u0430\u0442\u0438 \u0456\u0434\u0435\u0457 \u043d\u0430 \u0442\u0435, \u0449\u043e \u0440\u0435\u0430\u043b\u044c\u043d\u043e \u043f\u0440\u0430\u0446\u044e\u0454.",B.cv,"\u0422\u0438 \u0437\u0432\u0435\u0440\u0442\u0430\u0454\u0448 \u0443\u0432\u0430\u0433\u0443 \u043d\u0430 \u0442\u0435, \u044f\u043a \u043b\u044e\u0434\u0438 \u0431\u0430\u0447\u0430\u0442\u044c \u0456 \u0432\u0456\u0434\u0447\u0443\u0432\u0430\u044e\u0442\u044c \u043f\u0440\u043e\u0434\u0443\u043a\u0442.",B.cw,"\u0422\u043e\u0431\u0456 \u0446\u0456\u043a\u0430\u0432\u043e \u043f\u0440\u0430\u0446\u044e\u0432\u0430\u0442\u0438 \u0437 \u0434\u0430\u043d\u0438\u043c\u0438, \u0448\u0443\u043a\u0430\u0442\u0438 \u0437\u0430\u043a\u043e\u043d\u043e\u043c\u0456\u0440\u043d\u043e\u0441\u0442\u0456 \u0442\u0430 \u0437\u043d\u0430\u0445\u043e\u0434\u0438\u0442\u0438 \u0432 \u043d\u0438\u0445 \u0432\u0456\u0434\u043f\u043e\u0432\u0456\u0434\u0456.",B.cx,"\u0422\u0438 \u043b\u044e\u0431\u0438\u0448 \u043f\u0435\u0440\u0435\u0432\u0456\u0440\u044f\u0442\u0438, \u0434\u043e\u0441\u043b\u0456\u0434\u0436\u0443\u0432\u0430\u0442\u0438 \u0439 \u0437\u043d\u0430\u0445\u043e\u0434\u0438\u0442\u0438 \u0442\u0435, \u0449\u043e \u0456\u043d\u0448\u0456 \u043c\u043e\u0433\u043b\u0438 \u043d\u0435 \u043f\u043e\u043c\u0456\u0442\u0438\u0442\u0438.",B.cy,"\u0422\u043e\u0431\u0456 \u0432\u0430\u0436\u043b\u0438\u0432\u043e \u0437\u043d\u0430\u0445\u043e\u0434\u0438\u0442\u0438 \u0441\u043b\u0430\u0431\u043a\u0456 \u043c\u0456\u0441\u0446\u044f \u0442\u0430 \u0437\u0430\u0445\u0438\u0449\u0430\u0442\u0438 \u0441\u0438\u0441\u0442\u0435\u043c\u0438 \u0439 \u0434\u0430\u043d\u0456 \u0432\u0456\u0434 \u0437\u0430\u0433\u0440\u043e\u0437.",B.cz,"\u0422\u0438 \u0434\u0443\u043c\u0430\u0454\u0448 \u043f\u0440\u043e \u0442\u0435, \u044f\u043a \u0443\u0441\u0435 \u043f\u0440\u0430\u0446\u044e\u0454 \u0440\u0430\u0437\u043e\u043c, \u0437\u0430\u043b\u0438\u0448\u0430\u0454\u0442\u044c\u0441\u044f \u043d\u0430\u0434\u0456\u0439\u043d\u0438\u043c \u0456 \u0432\u0438\u0442\u0440\u0438\u043c\u0443\u0454 \u0437\u0440\u043e\u0441\u0442\u0430\u043d\u043d\u044f.",B.cA,"\u0422\u043e\u0431\u0456 \u043f\u043e\u0434\u043e\u0431\u0430\u0454\u0442\u044c\u0441\u044f \u0441\u0442\u0430\u0432\u0438\u0442\u0438 \u0437\u0430\u043f\u0438\u0442\u0430\u043d\u043d\u044f, \u0437\u043d\u0430\u0445\u043e\u0434\u0438\u0442\u0438 \u0441\u043f\u0440\u0430\u0432\u0436\u043d\u044e \u043f\u0440\u0438\u0447\u0438\u043d\u0443 \u043f\u0440\u043e\u0431\u043b\u0435\u043c\u0438 \u0442\u0430 \u0440\u043e\u0437\u0443\u043c\u0456\u0442\u0438, \u0449\u043e \u043f\u043e\u0442\u0440\u0456\u0431\u043d\u043e \u0437\u043c\u0456\u043d\u0438\u0442\u0438.",B.cB,"\u0422\u043e\u0431\u0456 \u0431\u043b\u0438\u0437\u044c\u043a\u043e \u043e\u0431\u2019\u0454\u0434\u043d\u0443\u0432\u0430\u0442\u0438 \u043b\u044e\u0434\u0435\u0439, \u0432\u0438\u0437\u043d\u0430\u0447\u0430\u0442\u0438 \u043f\u0440\u0456\u043e\u0440\u0438\u0442\u0435\u0442\u0438 \u0442\u0430 \u0432\u0435\u0441\u0442\u0438 \u043a\u043e\u043c\u0430\u043d\u0434\u0443 \u0434\u043e \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442\u0443."],t.jo)
